import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {
    static class Edge {
        int to;
        int time;
        int cost;

        Edge(int to, int time, int cost) {
            this.to = to;
            this.time = time;
            this.cost = cost;
        }
    }

    static class State implements Comparable<State> {
        int u;
        int cost;
        int time;

        State(int u, int cost, int time) {
            this.u = u;
            this.cost = cost;
            this.time = time;
        }

        @Override
        public int compareTo(State o) {
            return Integer.compare(this.time, o.time);
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int n = 0;
            while (b >= '0' && b <= '9') {
                n = n * 10 + (b - '0');
                b = readByte();
            }
            return n;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int V = scanner.nextInt();
        if (V == -1) return;
        int N = scanner.nextInt();
        int M = scanner.nextInt();

        ArrayList<Edge>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int t = scanner.nextInt();
            int p = scanner.nextInt();

            adj[u].add(new Edge(v, t, p));
            adj[v].add(new Edge(u, t, p));
        }

        int X = scanner.nextInt();
        int Y = scanner.nextInt();

        int[][] dist = new int[N + 1][V + 1];
        for (int i = 1; i <= N; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[X][0] = 0;
        pq.add(new State(X, 0, 0));

        int ans = -1;

        while (!pq.isEmpty()) {
            State curr = pq.poll();
            int u = curr.u;
            int c = curr.cost;
            int d = curr.time;

            if (d > dist[u][c]) {
                continue;
            }

            if (u == Y) {
                ans = d;
                break;
            }

            for (Edge edge : adj[u]) {
                int nextCost = c + edge.cost;
                if (nextCost <= V) {
                    int nextTime = d + edge.time;
                    if (nextTime < dist[edge.to][nextCost]) {
                        dist[edge.to][nextCost] = nextTime;
                        pq.add(new State(edge.to, nextCost, nextTime));
                    }
                }
            }
        }

        System.out.println(ans);
    }
}
